{"version":3,"sources":["../scss/feedback.scss","feedback.css","../scss/_mixins.scss","../scss/_variables.scss"],"names":[],"mappings":"AAIA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;EACA,gBAAA;ACHF;ADKE;EACE,gBAAA;ACHJ;;ADOA;EACE,aAAA;EACA,mBAAA;EACA,SAAA;ACJF;ADME;EACE,eAAA;EEpBA,uCAAA;EACA,gBFoBoC;EEnBpC,kBAAA;EACA,YCHW;EDIX,eFiB8B;ACAlC;ADEI;EACE,UAAA;ACAN;ADIE;EACE,WAAA;EACA,gBAAA;EACA,yBAAA;EACA,YAAA;EACA,kBAAA;EEjCA,uCAAA;EACA,gBFiCoC;EEhCpC,kBAAA;EACA,YCHW;EDIX,eF8B8B;ACElC;;ADEA;EAGI;IACE,eAAA;ECDJ;EDIA;IACE,sBAAA;IACA,oBAAA;ECFF;EDIE;IACE,aAAA;IACA,uBAAA;ECFJ;EDKE;IACE,eAAA;ECHJ;AACF","file":"feedback.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n\n.feedback {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n  margin-top: 20px;\n\n  & button {\n    max-width: 320px;\n  }\n}\n\n.feedback__label {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n\n  & p {\n    flex: 0 1 150px;\n    @include fonts($defaultColor, 14px, 400);\n\n    & span {\n      color: red;\n    }\n  }\n\n  & input, textarea {\n    width: 100%;\n    max-width: 320px;\n    border: 1px solid $gray;\n    padding: 7px;\n    border-radius: 7px;\n    @include fonts($defaultColor, 14px, 400);\n  }\n}\n\n@media (max-width:992px) {\n\n  .feedback {\n    & button {\n      max-width: none;\n    }\n  }\n  .feedback__label {\n    flex-direction: column;\n    align-items: initial;\n\n    & p {\n      flex: initial;\n      align-items: flex-start;\n    }\n\n    & input, textarea {\n      max-width: none;\n    }\n  }\n}",".feedback {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n  margin-top: 20px;\n}\n.feedback button {\n  max-width: 320px;\n}\n\n.feedback__label {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.feedback__label p {\n  flex: 0 1 150px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.feedback__label p span {\n  color: red;\n}\n.feedback__label input, .feedback__label textarea {\n  width: 100%;\n  max-width: 320px;\n  border: 1px solid #D4D4D4;\n  padding: 7px;\n  border-radius: 7px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n\n@media (max-width: 992px) {\n  .feedback button {\n    max-width: none;\n  }\n  .feedback__label {\n    flex-direction: column;\n    align-items: initial;\n  }\n  .feedback__label p {\n    flex: initial;\n    align-items: flex-start;\n  }\n  .feedback__label input, .feedback__label textarea {\n    max-width: none;\n  }\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);"]}2;\n$asideExitColor: rgb(0, 128, 0);"]}